namespace distdsp{constexpr int maxChannels=2;inline float dbToGain(float dB)noexcept{return juce::Decibels::decibelsToGain(dB);}inline float clamp01(float v)noexcept{return juce::jlimit(0.f,1.f,v);}inline float normalisePercent(float v)noexcept{return clamp01(v/100.f);}inline float lerp(float a,float b,float t)noexcept{return a+(b-a)*t;}struct LowPassState{void prepare(double s){sampleRate=s;reset();}void setSampleRate(double s)noexcept{sampleRate=s;}void reset()noexcept{state.fill(0);}float process(int c,float in,float hz)noexcept{float sr=juce::jmax(1.f,(float)sampleRate),cut=juce::jlimit(20.f,sr*.45f,hz),coef=std::exp(-juce::MathConstants<float>::twoPi*cut/sr);auto&x=state[(size_t)juce::jlimit(0,maxChannels-1,c)];x=x*coef+in*(1-coef);return x;}double sampleRate=44100;std::array<float,maxChannels>state{};};struct HighPassState{void prepare(double s){lowPass.prepare(s);}void setSampleRate(double s)noexcept{lowPass.setSampleRate(s);}void reset()noexcept{lowPass.reset();}float process(int c,float in,float hz)noexcept{return in-lowPass.process(c,in,hz);}LowPassState lowPass;};struct DCBlockerState{void prepare(double s){sampleRate=s;reset();update();}void setSampleRate(double s)noexcept{sampleRate=s;update();}void reset()noexcept{x1.fill(0);y1.fill(0);}float process(int c,float in)noexcept{auto i=(size_t)juce::jlimit(0,maxChannels-1,c);float out=in-x1[i]+coef*y1[i];x1[i]=in;y1[i]=out;return out;}private:void update()noexcept{coef=std::exp(-juce::MathConstants<float>::twoPi*18.f/juce::jmax(1.f,(float)sampleRate));}double sampleRate=44100;float coef=.995f;std::array<float,maxChannels>x1{},y1{};};struct SlewLimiterState{void reset()noexcept{state.fill(0);}float process(int c,float target,float step)noexcept{auto&v=state[(size_t)juce::jlimit(0,maxChannels-1,c)];v+=juce::jlimit(-step,step,target-v);return v;}std::array<float,maxChannels>state{};};inline float softClip(float s,float a)noexcept{float d=juce::jmax(.1f,a);return std::tanh(s*d)/std::tanh(d);}inline float foldback(float s,float t)noexcept{float q=juce::jmax(.05f,t);if(s>q||s<-q)s=std::abs(std::abs(std::fmod(s-q,q*4))-q*2)-q;return juce::jlimit(-1.f,1.f,s/q);}inline float legacyShapeSample(float s,float dg,float b,int v,float k)noexcept{if(v==0){float t=juce::jmap(b,0.f,1.f,1.f,.22f),d=s*dg,h=juce::jlimit(-t,t,d),so=std::tanh(d/juce::jmax(.05f,t))*t;return juce::jlimit(-1.f,1.f,lerp(h,so,clamp01(k))/juce::jmax(.05f,t));}if(v==1){float d=s*dg,bits=juce::jmap(1.f-b,0.f,1.f,4.f,14.f),levels=std::pow(2.f,bits);return juce::jlimit(-1.f,1.f,std::round(d*levels)/juce::jmax(1.f,levels));}float a=juce::jmap(b,0.f,1.f,0.f,.35f),x=s+a;return juce::jlimit(-1.f,1.f,std::tanh(x*dg)-std::tanh(a*dg));}inline float overdriveShapeSample(float s,float dg,float b,float h,int v)noexcept{float bias=juce::jmap(b,-.22f,.22f),t=juce::jmap(h,.28f,1.15f),d=s*dg+bias;if(v==0)return juce::jlimit(-1.f,1.f,std::tanh(d/t)*t);if(v==1){float c=d-.24f*d*d*d;return juce::jlimit(-1.f,1.f,lerp(std::tanh(d/t)*t,c,.42f));}float e=std::atan(d*1.9f)/std::atan(1.9f);return juce::jlimit(-1.f,1.f,lerp(e,softClip(d,2.8f),.4f));}inline float fuzzShapeSample(float s,float dg,float b,float o,int v)noexcept{float bias=juce::jmap(b,-.28f,.28f),d=s*dg+bias,x=v==0?std::atan(d*3.5f)/std::atan(3.5f):(v==1?foldback(d,.62f):softClip(std::sin(d*2),3.6f));if(o>.001f)x=lerp(x,softClip(std::abs(d)*1.4f-.35f,2.2f),clamp01(o));return juce::jlimit(-1.f,1.f,x);}inline float consoleShapeSample(float s,float dg,float b,float h,int v)noexcept{float t=juce::jmap(h,.4f,1.2f),bias=juce::jmap(b,-.14f,.14f),d=s*dg+bias,x=std::tanh(d/t)*t;if(v==1)x=lerp(x,softClip(d*.92f,1.6f),.25f);else if(v==2)x=lerp(x,std::atan(d*1.5f)/std::atan(1.5f),.4f);return juce::jlimit(-1.f,1.f,x);}inline float applyToneFocus(float s,int c,float t,float f,LowPassState&lp)noexcept{float tone=clamp01(t),fs=juce::jmap(juce::jlimit(0.f,100.f,f),.72f,1.28f),cut=juce::jmap(tone,180.f,16000.f),dark=lp.process(c,s,cut),hi=s-dark,bright=juce::jlimit(-1.25f,1.25f,s+hi*(.35f*fs));return juce::jmap(tone,dark,bright);}inline uint32_t fastRand(uint32_t&s)noexcept{s=s*1664525u+1013904223u;return s;}inline float fastRandSigned(uint32_t&s)noexcept{return((float)(fastRand(s)&0xffffu)/32767.5f)-1.f;}}
